// Fibonacci - Bottom-Up (Tabulation)
public int Fib(int n) {
    if (n <= 1) return n;
    int[] dp = new int[n + 1];
    dp[0] = 0; 
    dp[1] = 1;

    for(int i = 2; i <= n; i++) {
        // Tận dụng kết quả đã tính ở i-1 và i-2
        dp[i] = dp[i-1] + dp[i-2];
    }
    return dp[n];
}
